// Fixed test payload against the TEST script. Replace <<EXPECTED_ENV>> (e.g. DEV) and optionally <<EXISTING_JR_TASK_ID>> (a TK- id of an OPEN jr_title task on the TEST sheet).
// runExtended: set to true to also run the OPTIONAL steps 10-12 (termination create → approve, position change create → approve, listWorkflows).
// Default false keeps the core run (1-9) unchanged. The approvals need efx-bot to be HR/Admin (real session principal) — otherwise they report WARN.
const RUN_EXTENDED = false;
const cfg = { expectedEnv: '<<EXPECTED_ENV>>', existingJrTaskId: '<<EXISTING_JR_TASK_ID>>', runExtended: RUN_EXTENDED === true };
if (cfg.expectedEnv.startsWith('<<')) cfg.expectedEnv = '';
if (cfg.existingJrTaskId.startsWith('<<')) cfg.existingJrTaskId = '';
const pad = n => String(n).padStart(2, '0');
const ymd = d => d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
const now = new Date();
const hire = new Date(now.getTime() + 14 * 86400000);
const stamp = now.toISOString().replace(/[-:T.Z]/g, '').slice(0, 14);
const runStartIso = new Date(now.getTime() - 60000).toISOString();   // 1 min slack for clock skew vs Apps Script server time
const payload = {
  requesterName: 'EFX E2E (n8n)', requesterEmail: 'dbinns@team-group.com', dateRequested: ymd(now), hireDate: ymd(hire),
  newHireOrRehire: 'New Hire', employeeType: 'Direct Hire', employmentType: 'Salary',   // r2 enum: employeeType ∈ Direct Hire|Agency (was 'Salary' in the r1 brief)
  firstName: 'EFX Test', lastName: 'Hire' + stamp, positionTitle: 'Site Supervisor',
  siteName: 'Aurora', jobSiteNumber: 'INDIRECT - Aurora',
  reportingManagerName: 'David Binns', reportingManagerEmail: 'dbinns@team-group.com',
  systemAccess: 'Yes', systems: ['BOSS', 'SiteDocs Supervisor'], equipment: [],
  plan306090: 'Yes', jrRequired: 'Yes', jrAssignment: 'Site Supervisor',
  comments: 'EFX E2E test run ' + stamp + ' — safe to cancel'
};
const idSetup = { siteDocsWorkerId: 'EFX-TEST', siteDocsJobCode: 'Hourly 1', dssUsername: 'efx.test', dssPassword: 'Test-Only-Not-Real', setupNotes: 'EFX E2E test ' + stamp };
const actor = { id: 'n8n:efx-e2e-test', email: 'efx-bot@team-group.com', display: 'EFX E2E Test (n8n)' };
// Extended (optional) payloads — FormContracts r2 termination_request / position_change_request required keys.
const term = new Date(now.getTime() + 7 * 86400000);
const termination = {
  reqName: 'EFX E2E (n8n)', reqEmail: 'dbinns@team-group.com', empName: 'EFX Test Hire' + stamp, empType: 'Salary', siteName: 'Aurora',
  termDate: ymd(term), lastDayWorked: ymd(term), reason: 'Resigned', managerName: 'David Binns', managerEmail: 'dbinns@team-group.com',
  has_reports: 'No', comments: 'EFX E2E test run ' + stamp + ' — safe to cancel'
};
const positionChange = {
  reqName: 'EFX E2E (n8n)', reqEmail: 'dbinns@team-group.com', reqDate: ymd(now), firstName: 'EFX Test', lastName: 'Hire' + stamp,
  currentClass: 'Salary', effDate: ymd(hire), siteName: 'Aurora', changeType: ['Position Change'], titleOld: 'Site Supervisor', titleNew: 'Site Manager',
  currentTitle: 'Site Supervisor', currentManagerName: 'David Binns', currentManagerEmail: 'dbinns@team-group.com',
  comments: 'EFX E2E test run ' + stamp + ' — safe to cancel'
};
return [{ json: { cfg, stamp, runStartIso, payload, idSetup, actor, termination, positionChange } }];

// Optional assertion: a second ID Setup for the same workflow should be rejected (workflow already advanced).
const j = $input.first().json;
const errored = !!j.error;
return [{ json: { step: '6b', optional: true, pass: errored,
  note: errored ? 'Second ID Setup rejected as expected: ' + String(j.error.message || j.error)
                : 'WARN: second ID Setup was accepted — Forms did not reject a re-submit (optional assertion; a duplicate ID Setup Results row now exists)' } }];

// Two valid outcomes, depending on the Forms setting SAFETY_TRAINING_AT_SUBMIT:
//   false (default): the safety_onboarding task does not exist yet (created at ID Setup for hourly / after HR Verification for salary) → EFX E_NOT_FOUND
//   true            : the task exists from submit → dryRun returns { dryRun:true, wouldClose:true }
const j = $input.first().json;
if (j.error) {
  const m = String(j.error.message || j.error);
  const pass = m.includes('E_NOT_FOUND');
  return [{ json: { step: '8', pass, mode: 'SAFETY_TRAINING_AT_SUBMIT=false', note: pass ? 'E_NOT_FOUND as expected (safety task not created yet for a Salary hire)' : 'Unexpected error: ' + m } }];
}
const pass = j.dryRun === true && j.wouldClose === true;
return [{ json: { step: '8', pass, mode: 'SAFETY_TRAINING_AT_SUBMIT=true', note: pass ? 'dryRun resolved the safety task (exists at submit)' : 'Unexpected success shape: ' + JSON.stringify(j).slice(0, 300) } }];

// Termination approval: PASS when accepted; WARN when the real session principal (efx-bot) is not HR/Admin; FAIL otherwise.
const j = $input.first().json;
if (j.error) {
  const m = String(j.error.message || j.error);
  const forbidden = /E_FORBIDDEN|Access denied/i.test(m);
  return [{ json: { step: '10b', optional: true, pass: forbidden, warn: forbidden, note: forbidden ? 'WARN: approval refused — efx-bot@team-group.com is not in grp.forms.hr / CONFIG.ADMIN_EMAILS on this tier: ' + m : 'Unexpected error: ' + m } }];
}
return [{ json: { step: '10b', optional: true, pass: j.ok === true && j.success !== false, warn: false, note: j.message || 'approved' } }];

// Position change approval: PASS when accepted; WARN when the real session principal (efx-bot) is not HR/Admin; FAIL otherwise.
const j = $input.first().json;
if (j.error) {
  const m = String(j.error.message || j.error);
  const forbidden = /E_FORBIDDEN|Access denied/i.test(m);
  return [{ json: { step: '11b', optional: true, pass: forbidden, warn: forbidden, note: forbidden ? 'WARN: approval refused — efx-bot@team-group.com is not in grp.forms.hr / CONFIG.ADMIN_EMAILS on this tier: ' + m : 'Unexpected error: ' + m } }];
}
return [{ json: { step: '11b', optional: true, pass: j.ok === true && j.success !== false, warn: false, note: j.message || 'approved' } }];

// Builds the PASS/FAIL table. A node that never executed throws when referenced — that is how NOT RUN is detected.
const STEPS = [
  ['1', '1 Ping', 'n8n_ping → env'],
  ['2', '2 Contracts', 'n8n_contracts → forms include new_hire, id_setup'],
  ['3', '3 CreateInitialRequest', 'n8n_createInitialRequest → 5-digit internalEmployeeId'],
  ['4', '4 GetEmployeeId', 'n8n_getEmployeeId equals step 3'],
  ['5', '5 GetWorkflow', 'n8n_getWorkflow → checklist "ID Setup" Pending'],
  ['6', '6 SubmitIdSetup', 'n8n_submitIdSetup without internalEmployeeId'],
  ['6b', '6b verdict (optional)', 'second ID Setup rejected (optional)'],
  ['7', '7 ListTasks jr_title', 'n8n_listTasks jr_title == 0 before IT Setup'],
  ['7b', '7b CloseTask dryRun', 'n8n_closeTask dryRun on <<EXISTING_JR_TASK_ID>> (only if given)'],
  ['7c', '7c CloseJrTask real', 'n8n_closeJrTask on <<EXISTING_JR_TASK_ID>> (only if given)'],
  ['8', '8 verdict', 'n8n_assignSafetyTraining dryRun → E_NOT_FOUND | dryRun:true'],
  ['9', '9 Events since start', 'n8n_events → result event with our workflowId'],
  ['10', '10 CreateTerminationRequest', 'OPTIONAL (runExtended) n8n_createTerminationRequest → TERM_ id'],
  ['10b', '10b verdict (optional)', 'OPTIONAL n8n_submitTerminationApproval Approved (WARN if efx-bot is not HR/Admin)'],
  ['11', '11 CreatePositionChangeRequest', 'OPTIONAL n8n_createPositionChangeRequest → CHANGE_ id'],
  ['11b', '11b verdict (optional)', 'OPTIONAL n8n_submitPositionChangeApproval Approved (WARN if efx-bot is not HR/Admin)'],
  ['12', '12 ListWorkflows', 'OPTIONAL n8n_listWorkflows since start includes our ids']
];
const EXT = ['10', '10b', '11', '11b', '12'];
const get = (n) => { try { return $(n).first().json; } catch (e) { return undefined; } };
const incoming = $input.first().json;
const failed = incoming && incoming.status === 'FAIL' ? incoming : null;
const cfg = get('Test config') || {};
const created = get('3 CreateInitialRequest') || {};
const rows = STEPS.map(([id, node, what]) => {
  const out = get(node);
  let status, note = '';
  if (failed && String(failed.step) === id) { status = 'FAIL'; note = failed.message; }
  else if (out === undefined) { status = ((id === '7b' || id === '7c') && !(cfg.cfg && cfg.cfg.existingJrTaskId)) || (EXT.includes(id) && !(cfg.cfg && cfg.cfg.runExtended)) ? 'SKIPPED' : 'NOT RUN'; }
  else if (id === '6b') { status = out.pass ? 'PASS' : 'WARN'; note = out.note; }
  else if (id === '10b' || id === '11b') { status = out.warn ? 'WARN' : (out.pass ? 'PASS' : 'FAIL'); note = out.note; }
  else if (id === '8') { status = out.pass ? 'PASS' : 'FAIL'; note = out.mode + ' — ' + out.note; }
  else if (out.error) { status = 'FAIL'; note = String(out.error.message || out.error); }
  else { status = 'PASS'; if (id === '3') note = out.workflowId + ' / ' + out.internalEmployeeId; if (id === '1') note = 'env=' + out.env + ' apiVersion=' + out.apiVersion; }
  return { step: id, what, status, note };
});
const overall = failed || rows.some(r => r.status === 'FAIL') ? 'FAIL' : 'PASS';
const table = rows.map(r => r.step.padEnd(3) + ' ' + r.status.padEnd(8) + ' ' + r.what + (r.note ? '  — ' + r.note : '')).join('\n');
return [{ json: { overall, failedStep: failed ? failed.step : null, workflowId: created.workflowId || null, internalEmployeeId: created.internalEmployeeId || null, stamp: cfg.stamp || null, steps: rows, table,
  cleanup: [created.workflowId, (get('10 CreateTerminationRequest') || {}).workflowId, (get('11 CreatePositionChangeRequest') || {}).workflowId].filter(Boolean).map(id => 'Cancel ' + id + ' (EFX Test Hire' + (cfg.stamp || '') + ') from the TEST dashboard.').join(' ') || 'nothing created' } }];
